INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_aerial_top_down', 'seed_team_house', 'aerial-top-down', 'Aerial Top-Down', 'Straight-down drone photography — naturally graphic, band-friendly. Scale and overview themes.', 'Straight-down aerial drone photography: the world flattened into graphic pattern — paths, rooftops, fields and shadows reading as composition. Crisp natural light with long clean shadows giving depth to the flatness, true colour with gentle contrast, high-resolution clarity edge to edge. Framing balances one focal cluster against large calm areas of ground texture.', 'A small figure seen from directly above — readable by shadow, outfit colour and what they carry; the pattern around them does the storytelling.', 'oblique angles, horizon lines, tilt-shift blur, desaturated grading, night scenes', '["photographic","aerial","top-down","pattern"]', 'hand', '2026-08-16T20:44:22.460Z', '2026-08-16T20:44:22.460Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_art_deco', 'seed_team_house', 'art-deco', 'Art Deco', 'Gilded geometric symmetry and jewel tones — the milestone and premium-announcement look.', 'Art deco poster style: symmetrical geometric composition with fan motifs, sunbursts and stepped frames, deep jewel tones — emerald, sapphire, burgundy, black — with metallic gold accent lines that catch a soft sheen. Smooth lacquered finish, crisp hard edges, stylised elongated forms. Ornament is disciplined: a few strong repeating motifs, never filigree clutter. The whole frame feels like an engraved invitation.', 'Stylised into elegant elongated deco proportions, posed statuesque in profile or three-quarter, hair and clothing simplified into sleek geometric shapes.', 'photorealism, pastel palettes, rough texture, asymmetry without purpose, busy filigree', '["deco","gold","geometric","premium"]', 'hand', '2026-08-16T20:44:22.460Z', '2026-08-16T20:44:22.460Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_bauhaus_geometric', 'seed_team_house', 'bauhaus-geometric', 'Bauhaus Geometric', 'Primary-colour geometry on a strict grid — unkillable poster language for process and systems content.', 'Bauhaus composition: circles, triangles and bars in primary red, blue and yellow plus black, arranged on a strict underlying grid over off-white. Flat matte fills, no gradients, no texture beyond the faintest paper tone. Diagonals used deliberately for energy; overlaps create simple secondary shapes; huge amounts of disciplined negative space. Every element feels placed by a ruler and a reason.', 'Abstracted into the geometry — a circle for the head, angled bars for the body, one recognising detail (glasses arc, hair wedge) rendered as a clean shape.', 'gradients, texture, photographic elements, decorative flourish, more than five colours', '["bauhaus","geometric","primary","grid"]', 'hand', '2026-08-16T20:44:22.460Z', '2026-08-16T20:44:22.460Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_blueprint_schematic', 'seed_team_house', 'blueprint-schematic', 'Blueprint Schematic', 'White technical linework on Prussian blue, like a drafting table original. The "how it works" look — a defining 2026 trend.', 'Technical blueprint drafting: crisp white and pale-cyan line drawing on a deep Prussian blue ground, with a faint grid, thin ruled construction lines, dimension arrows and small circled callouts. Objects drawn in clean orthographic or exploded views with hatching for depth, flat matte finish, slight cyanotype unevenness in the blue. Composition organised like an engineering sheet — one main figure, satellites around it, generous margins.', 'Rendered as a white contour line drawing of them, schematic and elegant — glasses, hair and posture as clean linework, no shading beyond sparse hatching.', 'photographic texture, colour beyond blue and white, filled shapes, 3D rendering, grunge', '["blueprint","technical","line","blue"]', 'hand', '2026-08-16T20:44:22.460Z', '2026-08-16T20:44:22.460Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_cyanotype', 'seed_team_house', 'cyanotype', 'Cyanotype', 'Prussian-blue photographic process with chemical edges. Archival, scientific, quiet.', 'Cyanotype print: the whole image in Prussian blue and paper white, with the soft silhouette edges, chemical staining and brush-coated borders of a hand-made contact print. Tonal range compressed and luminous, highlights blooming slightly, handmade paper texture showing through the emulsion. Composition simple and botanical-plate calm, objects arranged with specimen-like care.', 'Rendered as a soft-edged cyanotype figure — features gently diffused, silhouette strong, like a photogram of a person more than a photograph.', 'any second colour, digital sharpness, clean straight borders, high contrast blacks', '["cyanotype","blue","process","archival"]', 'hand', '2026-08-16T20:44:22.460Z', '2026-08-16T20:44:22.460Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_embroidered_stitch', 'seed_team_house', 'embroidered-stitch', 'Embroidered Stitch', 'Visible thread on fabric, hooped and handmade. Rides the 2026 tactile-craft wave.', 'Hand embroidery on natural linen: every form built from visible stitches — satin stitch fills, chain stitch outlines, French knots for texture — with real thread sheen and slightly raised relief casting tiny shadows. Folk-bright palette of a few thread colours on the warm fabric ground, fabric weave clearly visible in the negative space, edges of shapes honestly stitch-stepped. Composition sits centred like a framed hoop piece.', 'Stitched as an embroidered figure — satin-stitch hair, a few precise stitches for the face, outfit in flat thread fills; charming, not precious.', 'printed-texture fakery, smooth vector edges, photographic elements, gradients, gloss', '["embroidery","thread","craft","tactile"]', 'hand', '2026-08-16T20:44:22.460Z', '2026-08-16T20:44:22.460Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_ligne_claire', 'seed_team_house', 'ligne-claire', 'Ligne Claire', 'Clean uniform outlines and flat colour, Franco-Belgian comic tradition. Crisp narrative clarity without anime''s drama.', 'Ligne claire comic illustration: uniform-weight clean black outlines around every form, flat unmodulated colour fills with no gradients, hatching or rendered shadow — at most a single flat cast-shadow shape. Bright, slightly chalky Franco-Belgian palette, even daylight clarity everywhere, backgrounds drawn with the same line discipline as the foreground. Composition calm and readable, like a classic album panel.', 'Drawn with the same clear line — simple dot-and-line facial features, real adult proportions, likeness in hair shape, glasses and dress.', 'variable line weight, cel-shading steps, manga stylisation, painterly texture, gradients', '["comic","ligne-claire","flat","clean"]', 'hand', '2026-08-16T20:44:22.460Z', '2026-08-16T20:44:22.460Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_long_exposure_night', 'seed_team_house', 'long-exposure-night', 'Long Exposure Night', 'Light trails and silky motion against tack-sharp stillness. Speed, momentum, progress.', 'Night long-exposure photography: streaming light trails and silky motion blur flowing through the frame while static elements stay tack-sharp. Deep clean blacks, saturated point lights blooming gently, cool ambient tones with one warm light source for contrast. Reflective surfaces double the lights; the exposure feels patient and deliberate, tripod-steady.', 'The one sharp, still presence in the flow — motion streaming past them, lit by the nearest practical light, clearly recognisable.', 'daylight, frozen action, grain, HDR halos, cluttered mid-tones', '["photographic","night","long-exposure","motion"]', 'hand', '2026-08-16T20:44:22.460Z', '2026-08-16T20:44:22.460Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_low_poly', 'seed_team_house', 'low-poly', 'Low Poly', 'Faceted triangular 3D with flat per-face shading. Clean tech-abstract geometry.', 'Low-poly 3D render: every form built from visible triangular facets with flat per-face shading — no smoothing, no textures. Soft ambient studio lighting gives each facet a distinct tone within a restrained palette of three or four hues plus their shades. Clean gradient-sky or single-colour backdrop, a subtle soft shadow under the scene, crisp silhouettes. Composition floats like a geometric diorama.', 'A faceted low-poly figure with readable proportions — hair, glasses and clothing as distinct colour groups of facets, no facial texture.', 'smooth surfaces, texture maps, outlines, photorealism, high-frequency detail', '["3d","low-poly","faceted","tech"]', 'hand', '2026-08-16T20:44:22.460Z', '2026-08-16T20:44:22.460Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_memphis_pop', 'seed_team_house', 'memphis-pop', 'Memphis Pop', 'Squiggles, terrazzo and candy brights — 80s postmodern play. Back and here to stay.', 'Memphis design: clashing squiggles, zigzags, grids and terrazzo speckle in candy brights — pink, teal, yellow, lilac — over a pale ground. Flat matte fills with bold black geometric accents, shapes scattered with deliberate irreverence but balanced weight. A drop shadow here and there in a flat offset colour, never soft. The whole frame feels like a playful 80s showroom pattern sheet.', 'A flat graphic figure built from Memphis shapes — triangle torso, squiggle hair energy, bold simple face — dropped confidently among the pattern.', 'gradients, photographic texture, muted palettes, minimalism, soft shadows', '["memphis","pop","pattern","playful"]', 'hand', '2026-08-16T20:44:22.460Z', '2026-08-16T20:44:22.460Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_naive_gouache', 'seed_team_house', 'naive-gouache', 'Naive Gouache', 'Charming wobbly gouache, storybook-bright. The human-touch look trending against AI polish.', 'Contemporary naive gouache illustration: flat opaque matte strokes with charmingly imperfect, wobbly shapes and edges that don''t quite meet. Bright storybook palette laid in confident single passes, visible paper tooth through thinner patches, no outlines — forms are held by colour against colour. Perspective is cheerfully wrong, scale playful, composition warm and generous.', 'Painted as a friendly naive figure — dot eyes, simple curved features, likeness carried by hair colour and outfit, proportions softly wrong on purpose.', 'clean vector edges, gradients, realistic anatomy, outlines, digital brush uniformity', '["gouache","naive","warm","storybook"]', 'hand', '2026-08-16T20:44:22.460Z', '2026-08-16T20:44:22.460Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_retro_airbrush', 'seed_team_house', 'retro-airbrush', 'Retro Airbrush', 'Smooth 80s airbrush gradients, sunset palette, slick poster sheen. Retro-futurism''s painterly wing.', '1980s airbrush poster art: silky graded shading with soft glows and chrome-adjacent highlights, laid in smooth sweeping passes. Sunset palette — magenta, orange, violet, deep blue — with a horizon glow and a few crisp white speculars. Surfaces look polished and slightly idealised; edges alternate razor-crisp against soft-faded. Finish is a slick printed poster with the faintest spray grain.', 'Painted in idealised airbrush portrait style — smooth graded skin planes, glowing rim light in the palette colours, hair with sweeping highlight bands.', 'flat fills, hard cel shading, film grain, muted palettes, digital photo realism', '["airbrush","retro","sunset","glow"]', 'hand', '2026-08-16T20:44:22.460Z', '2026-08-16T20:44:22.460Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_stained_glass', 'seed_team_house', 'stained-glass', 'Stained Glass', 'Lead-lined jewel panes with backlit glow. Strong at small sizes; made for story and values content.', 'Stained glass window: bold black lead lines dividing the image into cloisonné panes of translucent jewel-toned glass — ruby, cobalt, amber, emerald — each pane subtly varied in tone as if light passes through unevenly. Warm backlit glow, slight bubbling texture in the glass, composition organised into strong radial or arched panels. Forms are simplified to what leadwork can hold.', 'Rendered as a stained-glass figure — face and hands in warm amber panes, features drawn by the lead lines, hair and clothes as coloured glass segments.', 'photographic texture, fine gradient detail, thin outlines, flat matte fills, pastels', '["stained-glass","jewel","glow","panels"]', 'hand', '2026-08-16T20:44:22.460Z', '2026-08-16T20:44:22.460Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_studio_product', 'seed_team_house', 'studio-product', 'Studio Product', 'Seamless-backdrop commercial photography with controlled softbox light. The launch and feature-reveal look.', 'High-end studio product photography: a seamless single-colour cyclorama backdrop, large softbox key with a crisp specular highlight, clean fill, and a shallow soft contact shadow grounding every object. True colour, immaculate focus front to back on the hero, gentle falloff behind. Composition centred or on a clean third with generous margin, styled like a premium e-commerce hero shot.', 'Photographed as if for a premium brand campaign — even flattering studio light, crisp focus, relaxed professional presence, no props beyond what the scene demands.', 'location backgrounds, harsh shadows, lens flare, grain, cluttered styling, HDR', '["photographic","studio","product","clean"]', 'hand', '2026-08-16T20:44:22.460Z', '2026-08-16T20:44:22.460Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_tilt_shift_miniature', 'seed_team_house', 'tilt-shift-miniature', 'Tilt-Shift Miniature', 'Real scenes photographed to look like tiny models. Big-picture posts with instant charm.', 'Tilt-shift miniature photography: an elevated three-quarter aerial vantage with a narrow razor-sharp horizontal band of focus and heavy smooth blur above and below it. Slightly boosted saturation and contrast so the world reads as a hand-painted model; clean daylight with small crisp shadows. The scene keeps real-world detail but everything — vehicles, people, buildings — appears toy-scale.', 'A tiny sharp figure inside the focus band, readable by posture and outfit colour at miniature scale — never a close-up.', 'eye-level framing, full-frame sharpness, muted desaturated grades, night scenes, macro toys', '["photographic","tilt-shift","aerial","miniature"]', 'hand', '2026-08-16T20:44:22.460Z', '2026-08-16T20:44:22.460Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_ukiyo_e_woodblock', 'seed_team_house', 'ukiyo-e-woodblock', 'Ukiyo-e Woodblock', 'Japanese woodblock flatness with bokashi gradient wipes and mineral colour. Serene and timeless.', 'Ukiyo-e woodblock print: flat planes of muted mineral colour — indigo, ochre, sage, vermilion accents — separated by a delicate dark keyline, with bokashi gradient wipes softening skies and water. Visible woodgrain ghosting through large flat areas, washi paper tone in the ground, stylised waves, clouds and foliage drawn as rhythmic pattern. Composition uses bold asymmetry, high horizons and generous emptiness.', 'Drawn in ukiyo-e figure style — graceful line, flat colour robes or clothing, calm stylised features; likeness held by hair, glasses and stance.', 'western shading, photorealism, saturated modern palettes, thick outlines, gloss', '["ukiyo-e","woodblock","japanese","serene"]', 'hand', '2026-08-16T20:44:22.460Z', '2026-08-16T20:44:22.460Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_vintage_travel_poster', 'seed_team_house', 'vintage-travel-poster', 'Vintage Travel Poster', 'Mid-century travel-poster flatness: bold shapes, warm matte palette. Instantly premium and legible at thumbnail size — great for announcements.', 'Mid-century travel poster illustration: bold simplified colour blocks with screenprint-flat gradients, confident geometric forms, and clean silhouetted edges. Warm matte palette of mustard, teal, coral and cream on paper-toned ground, with subtle print texture. Strong diagonal or low-horizon composition with one heroic focal element scaled generously; everything reads at a glance from across the room.', 'Drawn as a poised poster figure — simplified planes, confident stance, likeness carried by silhouette, hair shape and outfit colour rather than facial detail.', 'photorealism, gradients beyond flat print wipes, thin fussy detail, neon colours, gloss', '["poster","mid-century","flat","warm"]', 'hand', '2026-08-16T20:44:22.460Z', '2026-08-16T20:44:22.460Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_voxel', 'seed_team_house', 'voxel', 'Voxel', 'Chunky 3D cubes with soft global light — pixel art''s 3D sibling. Playful tech charm.', 'Voxel 3D render: everything built from uniform small cubes, like a scene assembled from tiny blocks, with clean 45-degree lighting and soft global illumination shading each cube face distinctly. Saturated toy-like palette, crisp cube edges, a soft ambient shadow grounding the scene on a plain pastel field. Detail emerges from clever block placement, never from texture; the render itself is immaculate.', 'A voxel figure at readable scale — blocky proportions, hair and outfit as coloured cube clusters, a few well-placed cubes for the face.', 'smooth curves, texture maps, outlines, mixed cube sizes, photorealism', '["voxel","3d","blocks","playful"]', 'hand', '2026-08-16T20:44:22.460Z', '2026-08-16T20:44:22.460Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_woodcut_print', 'seed_team_house', 'woodcut-print', 'Woodcut Print', 'Hand-carved relief print with visible gouge marks — gravitas and craft in one. Part of the 2026 print revival.', 'Traditional woodcut relief print: heavy hand-carved black linework with visible gouge marks and chatter, bold areas of solid ink against untouched cream paper, one restrained spot colour laid slightly off-register. High contrast, rough ink-on-paper texture with uneven coverage at the edges of strokes. Composition is strong and frontal, forms simplified into carvable shapes with dramatic hatching for tone.', 'Carved as a bold portrait — thick contour lines, hatched shadow across one side of the face, expression grave and direct; likeness lives in the strong outline.', 'fine smooth lines, gradients, photographic detail, digital cleanliness, bright palettes', '["woodcut","print","carved","high-contrast"]', 'hand', '2026-08-16T20:44:22.460Z', '2026-08-16T20:44:22.460Z');
